import type { InterviewGuide, Question, RecruiterScreen, RubricLevel } from "@/shared/interview-kit-types";

/**
 * Quality and compliance checks for a generated Interview Kit — a port of
 * Susan's scripts/check_pack.py (Hiring Toolkit PRD §10). Same regexes, same
 * messages, split per part because the two parts are generated by separate
 * requests. Keep in sync with the Python; never relax a check without a reason
 * in the PRD. Runs after the JSON schema has passed.
 */

const BANNED =
  /\b(nationality|citizen(ship)?(?! beyond)|how old|your age|year of birth|born in|married|marital|children|kids|pregnan|religio|church|mosque|political|party member|disabilit|health condition|sick leave|maiden name|graduat(ed|ion) year|native speaker|mother tongue|accent)\b/i;
const HYPO = /^(how would you|what would you|imagine|if you were|suppose|what if)/i;
const PRESTIGE =
  /\b(ivy league|oxbridge|top[- ]tier (school|university)|prestigious|famous|big[- ]?(4|four)|faang|mckinsey|bcg|bain|elite (school|university))\b/i;
const VAGUE = /^\s*(strong|good|excellent|great|weak|poor)\b[^0-9]{0,40}$/i;
const SCALES: Record<string, string[]> = {
  PE: ["Limited", "Borderline", "Solid", "Outstanding"],
  CC: ["Limited", "Borderline", "Solid", "Outstanding"],
  LF: ["Limited", "Borderline", "Solid", "Outstanding"],
  MF: ["Aligned", "To discuss", "Material risk"],
};

type Result = { failures: string[]; warnings: string[] };
type FrameworkEntry = { no: number; name: string; core: boolean; rubric: Record<string, string>; questions: string[] };

function make() {
  const FAIL: string[] = [];
  const WARN: string[] = [];
  const scan = (where: string, text: string) => {
    const b = BANNED.exec(text);
    if (b) FAIL.push(`${where}: touches a protected or personal topic ("${b[0]}")`);
    if (text.includes("{{") || text.includes("{company")) FAIL.push(`${where}: unfilled placeholder`);
    const p = PRESTIGE.exec(text);
    if (p) WARN.push(`${where}: mentions prestige ("${p[0]}"); make sure it is not treated as evidence`);
  };
  const questions = (where: string, qs: Question[]) => {
    let used = 0;
    qs.forEach((q, i) => {
      scan(`${where} Q${i + 1}`, q.q);
      for (const p of q.probes) scan(`${where} Q${i + 1} probe`, p);
      if (HYPO.test(q.q.trim())) {
        used++;
        if (!q.probes.some((p) => /when have you|when did you/i.test(p))) {
          FAIL.push(`${where} Q${i + 1}: hypothetical question without a "When have you done something similar?" probe`);
        }
      }
    });
    return used;
  };
  const rubric = (where: string, rub: RubricLevel[]) => {
    for (const r of rub) {
      scan(`${where} rubric ${r.level}`, r.text);
      if (VAGUE.test(r.text)) FAIL.push(`${where} rubric ${r.level}: vague anchor with no observable evidence`);
      const words = r.text.split(/\s+/).filter(Boolean).length;
      if (words < 8) WARN.push(`${where} rubric ${r.level}: very short anchor (${words} words)`);
    }
  };
  return { FAIL, WARN, scan, questions, rubric };
}

const same = (a: string[], b: string[]) => a.length === b.length && a.every((x, i) => x === b[i]);

export function checkScreen(screen: RecruiterScreen): Result {
  const { FAIL, WARN, scan, questions, rubric } = make();
  const names = screen.areas.map((a) => a.name.toLowerCase());
  for (const must of ["job fit", "achiever pattern", "managerial fit", "context", "motivation", "passion", "must-have"]) {
    if (!names.some((n) => n.includes(must))) FAIL.push(`screen: missing area "${must}"`);
  }
  for (const a of screen.areas) {
    const n = a.name.toLowerCase();
    const levels = a.rubric.map((r) => r.level);
    if (n.includes("achiever") && !same(levels, ["Top 5%", "Top 20%", "Top 50%", "Below"])) {
      FAIL.push(`screen ${a.name}: scale must be Top 5% / Top 20% / Top 50% / Below`);
    } else if (n.includes("managerial") && !same(levels, ["Aligned", "Unclear", "Risk"])) {
      FAIL.push(`screen ${a.name}: scale must be Aligned / Unclear / Risk`);
    } else if (n.includes("must-have") && !same(levels, ["Met", "Not met"])) {
      FAIL.push(`screen ${a.name}: scale must be Met / Not met`);
    } else if (!["achiever", "managerial", "must-have"].some((k) => n.includes(k)) && !same(levels, ["High", "Medium", "Low"])) {
      FAIL.push(`screen ${a.name}: scale must be High / Medium / Low`);
    }
    if (questions(`screen ${a.name}`, a.questions) > 1) FAIL.push(`screen ${a.name}: more than one hypothetical question`);
    rubric(`screen ${a.name}`, a.rubric);
  }
  scan("screen intro", screen.intro);
  const ends = screen.running_order.map((r) => parseInt(r.minutes.split("-")[1] ?? "0", 10));
  const total = ends.length ? Math.max(...ends) : 0;
  if (total !== 60) FAIL.push(`screen: running order ends at ${total} min, must end at 60`);
  return { failures: FAIL, warnings: WARN };
}

export function checkInterviews(inter: InterviewGuide, fw: FrameworkEntry[]): Result {
  const { FAIL, WARN, scan, questions, rubric } = make();
  const keys = inter.attributes.map((a) => a.key);
  if (!same(keys, ["PE", "CC", "LF", "MF"])) FAIL.push(`interviews: attributes must be PE, CC, LF, MF in that order (got ${keys.join(", ")})`);
  const total = inter.attributes.reduce((s, a) => s + a.areas.length, 0);
  if (total < 10 || total > 22) FAIL.push(`interviews: ${total} areas, expected 10-22`);
  const seen = new Set<string>();
  for (const at of inter.attributes) {
    let hypo = 0;
    for (const x of at.areas) {
      if (!x.id.startsWith(at.key)) FAIL.push(`${x.id}: ID does not match attribute ${at.key}`);
      if (seen.has(x.id)) FAIL.push(`${x.id}: duplicate ID`);
      seen.add(x.id);
      const levels = x.rubric.map((r) => r.level);
      if (!same(levels, SCALES[at.key])) FAIL.push(`${x.id}: rubric levels ${levels.join(", ")} must be ${SCALES[at.key].join(", ")}`);
      const h = questions(x.id, x.questions);
      hypo += h;
      if (h > 1) FAIL.push(`${x.id}: more than one hypothetical question`);
      rubric(x.id, x.rubric);
      scan(`${x.id} what`, x.what);
    }
    if (at.key !== "LF" && hypo > 1) FAIL.push(`${at.key}: ${hypo} hypothetical questions, maximum one per attribute`);
  }
  const lf = inter.attributes.find((a) => a.key === "LF");
  if (lf) {
    const byNo = new Map(fw.map((c) => [c.no, c]));
    const nos: number[] = [];
    for (const x of lf.areas) {
      const c = x.framework_no != null ? byNo.get(x.framework_no) : undefined;
      if (!c) {
        FAIL.push(`${x.id}: Leadership areas must come from the framework (framework_no 1-17 missing)`);
        continue;
      }
      nos.push(c.no);
      if (x.id !== `LF${c.no}`) FAIL.push(`${x.id}: ID must be LF${c.no}`);
      if (x.name !== c.name) FAIL.push(`${x.id}: name must be the framework name "${c.name}"`);
      if (x.selection !== "core" && x.selection !== "role-specific") FAIL.push(`${x.id}: selection must be "core" or "role-specific"`);
      if (x.selection === "role-specific" && !x.why) WARN.push(`${x.id}: role-specific competency without a "why"`);
      for (const r of x.rubric) {
        if (!r.text.startsWith(c.rubric[r.level] ?? "\u0000")) {
          FAIL.push(`${x.id} rubric ${r.level}: must start with the framework indicator word for word`);
        }
      }
      for (const fq of c.questions) {
        if (!x.questions.some((q) => q.q.startsWith(fq.slice(0, 40)))) {
          WARN.push(`${x.id}: framework question not used: "${fq.slice(0, 60)}…"`);
        }
      }
    }
    const missing = fw.filter((c) => c.core && !nos.includes(c.no)).map((c) => c.no);
    if (missing.length) WARN.push(`LF: core competencies not selected: ${missing.join(", ")} (fine only if the hiring manager removed them)`);
    if (nos.length < 1 || nos.length > 10) FAIL.push(`LF: ${nos.length} competencies, expected 1-10 (recommended 7-8)`);
  }
  const pe = inter.attributes.find((a) => a.key === "PE");
  if (pe && !pe.areas.some((x) => x.must_have)) WARN.push("PE: no must-have area marked");
  return { failures: FAIL, warnings: WARN };
}
